import{_ as o,o as s,c as n,a as t}from"./app.83c7065c.js";const p="/assets/prototype-chain.83bf6d82.png",A=JSON.parse('{"title":"JavaScript中的原型链","description":"","frontmatter":{"title":"JavaScript中的原型链","date":"2019-03-24"},"headers":[],"relativePath":"2019/javascript-prototype-chain.md","lastUpdated":1786184870000}'),e={name:"2019/javascript-prototype-chain.md"},a=t(`<ul><li><a href="#%E5%8E%9F%E5%9E%8B%E9%93%BE%E7%9A%84%E5%89%8D%E6%8F%90%E8%A7%84%E5%88%99">原型链的前提规则</a></li><li><a href="#%E5%8E%9F%E5%9E%8B%E9%93%BE%E5%85%B3%E7%B3%BB%E8%AF%95%E9%AA%8C">原型链关系试验</a></li><li><a href="#%E8%AF%95%E9%AA%8C%E7%9A%84%E4%B8%80%E7%82%B9%E8%A7%A3%E9%87%8A">试验的一点解释</a></li><li><a href="#%E5%8E%9F%E5%9E%8B%E9%93%BE%E5%85%B3%E7%B3%BB%E5%9B%BE">原型链关系图</a></li></ul><hr><h3 id="原型链的前提规则" tabindex="-1">原型链的前提规则 <a class="header-anchor" href="#原型链的前提规则" aria-hidden="true">#</a></h3><ol><li><p><strong>任何对象都拥有<code>__proto__</code>属性，指向其 <code>构造函数 (constructor function)</code> 的 <code>原型 (prototype)</code> 对象</strong></p><ul><li>例： 假设有数组对象 a，因为它是由数组构造函数<code>Array</code>创建的，那么<code>a.__proto__</code>将指向<code>Array.prototype</code></li></ul></li></ol><p>这里可以引申出 2 个推论：</p><blockquote><p><strong>推论 1.1</strong>：因为<code>构造函数 (constructor function)</code>是函数，而函数都是对象，所以构造函数也是对象。它也有<code>__proto__</code>属性，<code>__proto__</code>指向构造函数之构造函数的<code>原型 (prototype)</code> 对象；</p></blockquote><blockquote><p><strong>推论 1.2</strong>：<code>原型 (prototype)</code> 对象也是对象，所以也有<code>__proto__</code>属性，并指向 Object 构造函数原型<code>Object.prototype</code>；</p></blockquote><p><strong>疑问 1.1</strong>：<code>Object.prototype</code>是否也是对象？如果是，那么它也应该有<code>__proto__</code>属性，这个属性应该指向它自身？如果不是对象，那它是什么？</p><ol start="2"><li><p><strong>任何函数都是 <code>函数 (Function)</code> 创建的实例，且拥有<code>prototype</code>属性，该属性指向函数对应的<code>原型 (prototype)</code> 对象<code>Function.prototype</code></strong></p><p>根据 2 和推论 1.1，可以得到推论：</p></li></ol><blockquote><p><strong>推论 2.1</strong>：构造函数既是对象，又是函数实例，因此它不仅拥有<code>__proto__</code>属性，也拥有<code>prototype</code>属性</p></blockquote><blockquote><p><strong>推论 2.2</strong>：构造函数的<code>__proto__</code>属性指向其上一级构造函数<code>原型 (prototype)</code> 对象，即<code>Function.prototype</code>, 它的<code>prototype</code>属性指向<code>[[constructor]].prototype</code></p></blockquote><p><strong>疑问 2.1</strong>：<code>Function</code>作为元构造函数，其自身又是哪个构造函数的实例呢？如果<code>Function</code>是自身的实例，那么其<code>__proto__</code>属性应该指向<code>Function.prototype</code>；如果不是，它的<code>__proto__</code>属性会指向哪里？</p><ol start="3"><li><p><strong>构造函数的<code>原型 (prototype)</code>对象都有一个<code>构造函数(constructor)</code>属性，指向其对应的构造函数</strong></p><ul><li>例：即 Array.prototype.constructor 将指向 Array</li></ul></li></ol><h3 id="原型链关系试验" tabindex="-1">原型链关系试验 <a class="header-anchor" href="#原型链关系试验" aria-hidden="true">#</a></h3><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#676E95;font-style:italic;">/*** 疑问1.1 ***/</span></span>
<span class="line"><span style="color:#89DDFF;">typeof</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Object</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// &#39;object&#39;</span></span>
<span class="line"><span style="color:#FFCB6B;">Object</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype </span><span style="color:#89DDFF;">===</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">null;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// false</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//解释：Object.prototype是对象，按照基础概念1，它有__proto__属性</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">Object</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">__proto__</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// null</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//解释：Object.prototype.__proto__指向null，它没有__proto__属性</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">Object</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype </span><span style="color:#89DDFF;">instanceof</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Object</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// false</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//解释：Object.prototype不是Object的实例</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/************************************************************/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/*** 疑问2.1***/</span></span>
<span class="line"><span style="color:#89DDFF;">typeof</span><span style="color:#A6ACCD;"> Function</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// &#39;function&#39;</span></span>
<span class="line"><span style="color:#A6ACCD;">Function </span><span style="color:#89DDFF;">instanceof</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// true</span></span>
<span class="line"><span style="color:#A6ACCD;">Function </span><span style="color:#89DDFF;">instanceof</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Object</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// true</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//解释：Function是构造函数，它是函数，也是对象，所以既有prototype属性，也有__proto__属性</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A6ACCD;">Function</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">__proto__ </span><span style="color:#89DDFF;">==</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// true</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//解释：根据推论1.1，Function的构造函数是它自己</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">typeof</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// &#39;function&#39;</span></span>
<span class="line"><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// undefined</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//解释：Function.prototype是函数，但它没有prototype属性</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype </span><span style="color:#89DDFF;">instanceof</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// fasle</span></span>
<span class="line"><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype </span><span style="color:#89DDFF;">instanceof</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Object</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// true</span></span>
<span class="line"><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">__proto__ </span><span style="color:#89DDFF;">==</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Object</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// true</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//解释：Function.prototype是函数，但它不是Function的实例，却是Object的实例</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">typeof</span><span style="color:#A6ACCD;"> Object</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// &#39;function&#39;</span></span>
<span class="line"><span style="color:#A6ACCD;">Object </span><span style="color:#89DDFF;">instanceof</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// true</span></span>
<span class="line"><span style="color:#A6ACCD;">Object</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">__proto__ </span><span style="color:#89DDFF;">==</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">Function</span><span style="color:#89DDFF;">.</span><span style="color:#A6ACCD;">prototype</span><span style="color:#89DDFF;">;</span><span style="color:#A6ACCD;"> </span><span style="color:#676E95;font-style:italic;">// true</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">//解释：Object是构造函数，它是Function的实例</span></span>
<span class="line"></span></code></pre></div><p>这里出现了 2 个矛盾点，集中在<code>Object.prototype</code>和<code>Function.prototype</code>这 2 个对象：</p><ol><li><code>Object.prototype</code>是对象，却不是 Object 创建的</li><li><code>Function.prototype</code>是函数，却不是 Function 创建的，而是由 Object 创建，但 Object 明明是 Function 的实例</li></ol><p>如果说按照常理，第一点已经怪异到看不懂，那么第二点则是直接变成了“先有鸡 （Function），还是先有蛋 （Object）”的哲学拷问。</p><h3 id="试验的一点解释" tabindex="-1">试验的一点解释 <a class="header-anchor" href="#试验的一点解释" aria-hidden="true">#</a></h3><p>逻辑上这样自然说不通，那么只能说明一开始的前提规则错了，或者更具体点说，提到的这 2 个对象是超越规则的存在，不受前提规则的约束。查了下标准，果然这两个东西是基于规则创建的，为了兼容旧版本 JS 设定了一些规则，和构造函数其实没什么关系。</p><p><strong>关于 Object.prototype（注意加粗部分）</strong></p><blockquote><p>ECMA-262 19.1.3 Properties of the Object Prototype Object</p><p>The Object prototype object is the intrinsic object %ObjectPrototype%. <strong>The Object prototype object is an ordinary object</strong>.</p><p><strong>The value of the [[Prototype]] internal slot of the Object prototype object is null</strong> and the initial value of the [[Extensible]] internal slot is true.</p></blockquote><p><strong>关于 Function.prototype（注意加粗部分）</strong></p><blockquote><p>ECMA-262 19.2.3 Properties of the Function Prototype Object</p><p>The Function prototype object is the intrinsic object %FunctionPrototype%. The Function prototype object is itself a built-in function object. When invoked, it accepts any arguments and returns undefined. It does not have a [[Construct]] internal method so it is not a constructor.</p><p><strong>NOTE - The Function prototype object is specified to be a function object to ensure compatibility with ECMAScript code that was created prior to the ECMAScript 2015 specification.</strong></p><p>The value of the [[Prototype]] internal slot of the Function prototype object is the intrinsic object %ObjectPrototype% (19.1.3). The initial value of the [[Extensible]] internal slot of the Function prototype object is true.</p><p><strong>The Function prototype object does not have a prototype property.</strong></p><p>The value of the length property of the Function prototype object is 0.</p><p>The value of the name property of the Function prototype object is the empty String.</p></blockquote><h3 id="原型链关系图" tabindex="-1">原型链关系图 <a class="header-anchor" href="#原型链关系图" aria-hidden="true">#</a></h3><p>最后附上一张自己理解的图，权当费脑子的证明吧</p><p><img src="`+p+'" alt="prototype chain"></p>',27),l=[a];function c(r,i,y,F,D,C){return s(),n("div",null,l)}const u=o(e,[["render",c]]);export{A as __pageData,u as default};
